from pathlib import Path
import re

p = Path('news.py')
text = p.read_text(encoding='utf-8')
if 'from google import genai' in text and 'OPENAI_API_KEY' not in text:
    print('news.py already migrated to Gemini')
    raise SystemExit(0)

text = text.replace('from openai import OpenAI, RateLimitError\n', 'from google import genai\nfrom google.genai import types\n')

retry_block = '''# Gemini 2.5 Flash-Lite free tier is intentionally paced conservatively.\n# The job runs only every four hours, so reliability matters more than speed.\nMIN_API_INTERVAL_SECONDS = 8.0\n_last_api_call_started = 0.0\n\n\ndef _pace_api_calls(label: str) -> None:\n    global _last_api_call_started\n    now = time.monotonic()\n    remaining = MIN_API_INTERVAL_SECONDS - (now - _last_api_call_started)\n    if _last_api_call_started and remaining > 0:\n        print(f"API pacing before {label}: waiting {remaining:.1f}s...")\n        time.sleep(remaining)\n    _last_api_call_started = time.monotonic()\n\n\ndef gemini_generate_with_retry(\n    client: genai.Client,\n    *,\n    label: str,\n    model: str,\n    contents: str,\n    config: types.GenerateContentConfig,\n    max_retries: int = 6,\n):\n    """Gemini call with pacing and retry for free-tier 429/5xx responses."""\n    global _last_api_call_started\n    for attempt in range(max_retries + 1):\n        _pace_api_calls(label)\n        try:\n            return client.models.generate_content(model=model, contents=contents, config=config)\n        except Exception as exc:\n            message = str(exc)\n            transient = any(x in message for x in ("429", "RESOURCE_EXHAUSTED", "503", "UNAVAILABLE", "500", "INTERNAL"))\n            if not transient or attempt >= max_retries:\n                raise\n            wait = min(120.0, 15.0 * (1.7 ** attempt))\n            m = re.search(r"retry(?:Delay| after)?[^0-9]*([0-9.]+)s", message, re.IGNORECASE)\n            if m:\n                wait = max(wait, float(m.group(1)) + 3.0)\n            print(f"Temporary Gemini limit/error for {label}; waiting {wait:.1f}s ({attempt + 1}/{max_retries})...")\n            time.sleep(wait)\n            _last_api_call_started = time.monotonic() - MIN_API_INTERVAL_SECONDS\n\n\ndef _response_text(response: Any) -> str:\n    value = getattr(response, "text", None)\n    if value:\n        return value\n    try:\n        parts = response.candidates[0].content.parts\n        return "\\n".join(getattr(part, "text", "") or "" for part in parts).strip()\n    except Exception:\n        return ""\n\n'''
text, n = re.subn(r'# The collector can consume.*?(?=def read_json)', lambda _m: retry_block, text, count=1, flags=re.S)
if n != 1:
    raise SystemExit('Could not replace OpenAI retry block')

collect_block = '''def collect_batch(\n    client: genai.Client,\n    batch_name: str,\n    batch_prompt: str,\n    domains: list[str],\n    cfg: dict[str, Any],\n    now: datetime,\n) -> list[dict[str, Any]]:\n    """Search with Gemini grounding, then normalize the findings into strict JSON."""\n    lookback = int(cfg["lookback_hours"])\n    since = now - timedelta(hours=lookback)\n    candidate_limit = int(cfg["web_search"]["max_candidates_per_batch"])\n    allowed = ", ".join(domains) if domains else "любые разумные первичные или новостные сайты"\n\n    search_prompt = f"""\nСегодня {now:%Y-%m-%d %H:%M} по часовому поясу {cfg['timezone']}.\nНайди свежие материалы преимущественно после {since:%Y-%m-%d %H:%M}.\n\nРедакционная задача:\n{batch_prompt}\n\nИсточники: {allowed}.\nЕсли перечислены домены, ищи именно по ним и не подменяй их другими сайтами.\nНайди до {candidate_limit} сильных кандидатов; слабые не добавляй.\nДля каждого укажи: заголовок, прямой URL страницы, домен, дату/время если известно,\nкатегорию, 1–2 коротких предложения о событии и одно предложение почему это интересно.\nЕсли это мем/Reddit-комментарий — явно отметь это и не выдумывай текст.\n""".strip()\n\n    search_response = gemini_generate_with_retry(\n        client,\n        label=f"search:{batch_name}",\n        model=cfg["models"]["collector"],\n        contents=search_prompt,\n        config=types.GenerateContentConfig(\n            tools=[types.Tool(google_search=types.GoogleSearch())],\n            max_output_tokens=int(cfg["web_search"].get("search_max_output_tokens", 6000)),\n            temperature=0.2,\n        ),\n    )\n    raw = _response_text(search_response)\n    if not raw:\n        print(f"Gemini search returned no text for {batch_name}.")\n        return []\n\n    parser_prompt = f"""\nПреобразуй результаты поиска ниже в структурированный список кандидатов.\nНе добавляй фактов или URL, которых нет в результатах.\nМаксимум {candidate_limit} элементов. Пиши очень компактно.\nЕсли URL или дата неясны — оставь пустую строку.\nДля мемов/комментариев is_comment_or_meme=true; ничего не сочиняй.\n\nРЕЗУЛЬТАТЫ ПОИСКА:\n{raw}\n""".strip()\n\n    parse_response = gemini_generate_with_retry(\n        client,\n        label=f"parse:{batch_name}",\n        model=cfg["models"]["collector"],\n        contents=parser_prompt,\n        config=types.GenerateContentConfig(\n            response_mime_type="application/json",\n            response_json_schema=candidate_schema(),\n            max_output_tokens=int(cfg["web_search"].get("collector_max_output_tokens", 5000)),\n            temperature=0.0,\n        ),\n    )\n    value = _response_text(parse_response)\n    try:\n        payload = json.loads(value)\n    except json.JSONDecodeError as exc:\n        print(f"Gemini parser returned malformed JSON for {batch_name}: {exc}; skipping batch.")\n        return []\n\n    items = payload.get("items", [])[:candidate_limit]\n    if domains:\n        allowed_domains = {normalize_domain(d) for d in domains}\n        filtered = []\n        for item in items:\n            domain = normalize_domain(item.get("source_domain", "") or item.get("url", ""))\n            if any(domain == d or domain.endswith("." + d) for d in allowed_domains):\n                filtered.append(item)\n        items = filtered\n    return items\n\n\n'''
text, n = re.subn(r'def collect_batch\(.*?(?=def enrich_candidates)', lambda _m: collect_block, text, count=1, flags=re.S)
if n != 1:
    raise SystemExit('Could not replace collect_batch')

text = text.replace('client: OpenAI,', 'client: genai.Client,')
text = text.replace('        "candidates": candidates\n', '        "candidates": candidates,\n')

editor_loop = '''    for attempt in range(2):\n        response = gemini_generate_with_retry(\n            client,\n            label="editor",\n            model=cfg["models"]["editor"],\n            contents=prompt,\n            config=types.GenerateContentConfig(\n                response_mime_type="application/json",\n                response_json_schema=edition_schema(),\n                max_output_tokens=int(cfg.get("editor_max_output_tokens", 8000)),\n                temperature=0.15,\n            ),\n        )\n        value = _response_text(response)\n        try:\n            return json.loads(value)\n        except json.JSONDecodeError as exc:\n            print(f"Editor returned malformed JSON: {exc}.")\n            if attempt == 0:\n                print("Retrying editor after 20s...")\n                time.sleep(20)\n'''
text, n = re.subn(r'    for attempt in range\(2\):.*?(?=    raise RuntimeError\("Editor could not produce)', lambda _m: editor_loop, text, count=1, flags=re.S)
if n != 1:
    raise SystemExit('Could not replace editor API loop')

old_main = '''    if not os.getenv("OPENAI_API_KEY"):\n        raise SystemExit("Нет OPENAI_API_KEY. Скопируйте .env.example в .env и добавьте ключ.")\n\n    client = OpenAI()\n'''
new_main = '''    if not os.getenv("GEMINI_API_KEY"):\n        raise SystemExit("Нет GEMINI_API_KEY. Добавьте бесплатный ключ Gemini в GitHub Actions secret.")\n\n    client = genai.Client(api_key=os.environ["GEMINI_API_KEY"])\n'''
if old_main not in text:
    raise SystemExit('Could not find OpenAI client initialization')
text = text.replace(old_main, new_main, 1)

if 'OpenAI' in text or 'OPENAI_API_KEY' in text or 'create_response_with_retry' in text:
    raise SystemExit('Migration incomplete: OpenAI references remain')

p.write_text(text, encoding='utf-8')
print('Migrated news.py from OpenAI to Gemini')
